(function(){try{var t=localStorage.getItem('webkit-theme')||'light';if(t==='system'){t=window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';}if(t!=='dark'){t='light';}document.documentElement.setAttribute('data-theme',t);var p=localStorage.getItem('webkit-palette-'+t);if(p&&p!=='default'&&["default","catppuccin","gruvbox","nord","one","rose-pine","solarized","tokyo-night"].indexOf(p)!==-1){document.documentElement.setAttribute('data-palette',p);}var s=parseInt(localStorage.getItem('webkit-size'),10);if(!isNaN(s)){s=Math.max(12,Math.min(24,s));document.documentElement.style.fontSize=s+'px';}}catch(e){}})();
